function routeTriage(s) {
  if (s.category === 'other' || s.triageConfidence < 0.5) return 'human';
  if (s.category === 'billing' && s.amount > 100) return 'approval';
  return 'draft';
}
const tests = [
  [{ category: 'shipping', triageConfidence: 0.9, amount: 20 }, 'draft'],
  [{ category: 'other', triageConfidence: 0.9, amount: 20 }, 'human'],
  [{ category: 'shipping', triageConfidence: 0.3, amount: 20 }, 'human'],
  [{ category: 'billing', triageConfidence: 0.9, amount: 500 }, 'approval'],
  [{ category: 'billing', triageConfidence: 0.9, amount: 20 }, 'draft'],
];
let pass = 0;
for (const [input, expected] of tests) {
  const got = routeTriage(input);
  if (got === expected) pass++;
  else console.log('MISS ' + JSON.stringify(input) + ' -> ' + got);
}
console.log(pass + '/' + tests.length + ' branches covered');

